/* Floats above every screen; the app shell renders it once. Bottom-end corner,
 * clear of content and of the concierge/side panels both apps hang there. */
.session-pill {
  position: fixed;
  inset-block-end: var(--space-6);
  inset-inline-end: var(--space-6);
  z-index: var(--z-toast, 60);
  display: flex;
  align-items: stretch;
  border-radius: var(--radius-full);
  background: var(--card);
  border: var(--surface-edge);
  box-shadow: var(--card-shadow);
  overflow: hidden;
}

.session-pill-main {
  display: flex;
  align-items: center;
  gap: var(--space-3);
  padding-block: var(--space-2);
  padding-inline: var(--space-4);
  background: none;
  color: var(--foreground);
}

.session-pill-dot {
  inline-size: var(--space-2);
  block-size: var(--space-2);
  border-radius: var(--radius-full);
  background: var(--destructive-emphasis);
  animation: session-pill-pulse 1.6s ease-in-out infinite;
}

.session-pill[data-tone='warning'] .session-pill-dot {
  background: var(--warning-emphasis);
  animation: none;
}

.session-pill-label {
  font-weight: var(--font-weight-medium);
}

.session-pill-timer {
  font-variant-numeric: tabular-nums;
  color: var(--muted-foreground);
}

.session-pill-action {
  display: inline-flex;
  align-items: center;
  gap: var(--space-1);
  /* `--link`, not `--primary`: the brand fill is a SURFACE colour and stays
   * brand-400 in dark, where it measures 2.08:1 as ink on the pill's card. The
   * link role is the same idea said in ink and it moves to brand-200 in dark,
   * which is what every other "text that goes somewhere" in this system uses.
   * Measured against the pixels behind it (2026-09-03). */
  color: var(--link);
  font-weight: var(--font-weight-medium);
}

.session-pill-dismiss {
  display: inline-flex;
  align-items: center;
  padding-inline: var(--space-3);
  border-inline-start: var(--surface-edge);
  background: none;
  color: var(--muted-foreground);
}

.session-pill-dismiss:hover {
  color: var(--foreground);
}

@keyframes session-pill-pulse {
  50% {
    opacity: 0.4;
  }
}

@media (prefers-reduced-motion: reduce) {
  .session-pill-dot {
    animation: none;
  }
}

/* THE TONE IS THE LOUDNESS. A live thing with a cost — an emergency call parked
 * behind another screen, a recording running — is painted in its tone at full
 * strength; a reminder the reader may put away stays the card with the tone as a
 * dot. One product kept a hand-written copy of this pill for two weeks because
 * the card version "blended into the chrome", and it was right about the case it
 * had. (2026-09-04)
 *
 * Everything inside inverts together — the dot, the timer, the action and the
 * dismiss — which is what makes this a fill rather than a background. */
.session-pill[data-tone='danger'] {
  background: var(--destructive);
  border-color: transparent;
}
.session-pill[data-tone='danger'] .session-pill-main,
.session-pill[data-tone='danger'] .session-pill-label,
.session-pill[data-tone='danger'] .session-pill-timer,
.session-pill[data-tone='danger'] .session-pill-action,
.session-pill[data-tone='danger'] .session-pill-dismiss {
  color: var(--destructive-foreground);
}
/* The dot cannot be the tone on a pill painted in it: it becomes the ink, so it
 * stays a mark rather than a colour. */
.session-pill[data-tone='danger'] .session-pill-dot { background: currentcolor; }
